pub struct Parsed {
    pub index: usize,
    pub values: Vec<String>,
    pub flag_l: bool,
}

pub enum Outcome {
    NoCommand,
    TopHelp,
    Command(Parsed),
    Error(String),
}

fn usage_of(spec: &CmdSpec, app: &str) -> String {
    spec.usage.replace("{app}", app)
}

fn error(body: String, usage: Option<&str>) -> Outcome {
    let mut text = format!("error: {body}\\n\\n");
    if let Some(u) = usage {
        text.push_str(&format!("USAGE:\\n    {}\\n\\n", u.replace("\\n", "\\n    ")));
    }
    text.push_str("For more information try --help\\n");
    Outcome::Error(text)
}

fn unexpected(arg: &str, usage: &str, subcommand_hint: bool) -> Outcome {
    let mut body = format!(
        "Found argument '{arg}' which wasn't expected, or isn't valid in this context\\n"
    );
    if arg.starts_with('-') {
        body.push_str(&format!(
            "\\n\\tIf you tried to supply `{arg}` as a value rather than a flag, use `-- {arg}`\\n"
        ));
    } else if subcommand_hint {
        body.push_str(&format!(
            "\\n\\tIf you tried to supply `{arg}` as a subcommand, remove the '--' before it.\\n"
        ));
    }
    error(body, Some(usage))
}

fn missing_required(missing: &[&str], usage: &str) -> Outcome {
    let list: Vec<String> = missing.iter().map(|m| format!("    {m}")).collect();
    error(format!(
        "The following required arguments were not provided:\\n{}",
        list.join("\\n")
    ), Some(usage))
}

fn invalid_value(value: &str, display: &str, possible: &[&str]) -> Outcome {
    error(
        format!(
            "\\"{value}\\" isn't a valid value for '{display}'\\n\\t[possible values: {}]",
            possible.join(", ")
        ),
        None,
    )
}

fn empty_value(display: &str) -> Outcome {
    error(
        format!("The argument '{display}' requires a value but none was supplied"),
        None,
    )
}

fn help_page(spec: &CmdSpec, app: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!("{app}-{} \\n", spec.name));
    out.push_str(spec.about);
    out.push_str("\\n\\nUSAGE:\\n");
    for line in usage_of(spec, app).split('\\n') {
        out.push_str(&format!("    {line}\\n"));
    }
    if !spec.args.is_empty() {
        out.push_str("\\nARGS:\\n");
        let width = spec
            .args
            .iter()
            .map(|a| a.display.chars().count())
            .max()
            .unwrap_or(0)
            + 4;
        for arg in spec.args {
            let pad = " ".repeat(width - arg.display.chars().count());
            let mut lines = arg.help.split('\\n');
            let first = lines.next().unwrap_or("");
            out.push_str(&format!("    {}{pad}{first}\\n", arg.display));
            for extra in lines {
                out.push_str(&format!("{}{extra}\\n", " ".repeat(4 + width)));
            }
        }
    }
    out.push_str("\\nOPTIONS:\\n");
    for opt in spec.options {
        out.push_str(&format!("    {opt}\\n"));
    }
    out.push_str("    -h, --help    Print help information\\n");
    out
}

pub fn print_help_page(index: usize, app: &str) {
    print!("{}", help_page(&COMMANDS[index], app));
}

pub fn print_banner() {
    print!("{BANNER}");
}

pub fn parse(argv: &[String], app: &str) -> Outcome {
    let top_usage = format!("{app} <SUBCOMMAND>");
    let mut i = 0usize;
    let mut after = false;
    while i < argv.len() {
        let arg = &argv[i];
        if !after && arg == "--" {
            after = true;
            i += 1;
            continue;
        }
        if !after && (arg == "-h" || arg == "--help") {
            return Outcome::TopHelp;
        }
        if !after && arg.starts_with('-') {
            return unexpected(arg, &top_usage, false);
        }
        let index = COMMANDS
            .iter()
            .position(|c| c.name == arg.as_str() || c.aliases.contains(&arg.as_str()));
        match index {
            Some(index) => return parse_command(index, &argv[i + 1..], app),
            None => return unexpected(arg, &top_usage, after),
        }
    }
    Outcome::NoCommand
}

fn parse_command(index: usize, argv: &[String], app: &str) -> Outcome {
    let spec = &COMMANDS[index];
    let usage = usage_of(spec, app);
    let mut values: Vec<String> = Vec::new();
    let mut flag_l = false;
    let mut after = false;
    let mut i = 0usize;
    while i < argv.len() {
        let arg = &argv[i];
        if !after && arg == "--" {
            after = true;
            i += 1;
            continue;
        }
        if !after && arg.starts_with('-') && arg.as_str() != "-" {
            match arg.as_str() {
                "-h" | "--help" => {
                    print_help_page(index, app);
                    process::exit(0);
                }
                "-l" if spec.has_l => {
                    if flag_l {
                        return error(
                            "The argument '-l' was provided more than once, but cannot be used multiple times\\n".to_string(),
                            Some(&usage),
                        );
                    }
                    flag_l = true;
                }
                _ => return unexpected(arg, &usage, false),
            }
            i += 1;
            continue;
        }
        let slot = values.len();
        if slot >= spec.args.len() {
            return unexpected(arg, &usage, false);
        }
        let arg_spec = &spec.args[slot];
        if arg_spec.clap_checked && !arg_spec.possible.is_empty() && !arg_spec.possible.contains(&arg.as_str()) {
            return invalid_value(arg, arg_spec.display, arg_spec.possible);
        }
        if arg_spec.kind == Kind::Path && arg.is_empty() {
            return empty_value(arg_spec.display);
        }
        values.push(arg.clone());
        i += 1;
    }
    if spec.name == "vault" {
        if values.len() == 1 {
            return missing_required(&["<vault location>"], &usage);
        }
    } else {
        let missing: Vec<&str> = spec
            .args
            .iter()
            .enumerate()
            .filter(|(i, a)| a.required && values.len() <= *i)
            .map(|(_, a)| a.display)
            .collect();
        if !missing.is_empty() {
            return missing_required(&missing, &usage);
        }
    }
    Outcome::Command(Parsed { index, values, flag_l })
}
