    println!("note {} created", blue(name));
    Ok(())
}

fn folder(state: &mut State, name: &str) -> JotResult<()> {
    Vault::check_name(name)?;
    let vault = current_vault(state)?;
    let path = vault.item_path(name);
    if path.exists() {
        return Err(format!("a folder named {name} already exists in this location").into());
    }
    fs::create_dir(&path)?;
    println!("folder {} created", blue(name));
    Ok(())
}

fn open(state: &mut State, name: &str) -> JotResult<()> {
    Vault::check_name(name)?;
    let vault = current_vault(state)?;
    let path = vault.note_path(name);
    if !path.exists() {
        return Err(format!("note {name} not found").into());
    }
    let editor = which(&state.config.editor)
        .ok_or_else(|| JotError::Message(String::from("editor not found")))?;
    Command::new(editor).arg(path).status()?;
    Ok(())
}

fn opdir(state: &mut State) -> JotResult<()> {
    let vault = current_vault(state)?;
    let path = vault.folder_path();
    Command::new("xdg-open").arg(path).spawn()?;
    Ok(())
}

fn chdir(state: &mut State, path: &str) -> JotResult<()> {
    let vault = current_vault(state)?;
    let target = vault.folder_path().join(path);
    if !target.exists() {
        return Err("couldn't find the path specified".into());
    }
    let root = vault.root().canonicalize().unwrap_or_default();
    let target = match target.canonicalize() {
        Ok(path) => path,
        Err(_) => return Err("couldn't find the path specified".into()),
    };
    if !target.starts_with(&root) {
        return Err("path crosses the bounds of vault".into());
    }
    let current = vault.folder_path().canonicalize().unwrap_or_default();
    if target == current {
        return Err("new location is same as old location".into());
    }
    let relative = target
        .strip_prefix(&root)
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_default();
    state.set_folder(&relative)
}

fn list(state: &mut State, kind: Option<&str>) -> JotResult<()> {
    let vault = current_vault(state)?;
    let filter = match kind {
        Some(kind) => match ItemKind::from(kind) {
            Some(ItemKind::Note) => Some(true),
            Some(ItemKind::Folder) => Some(false),
            _ => {
                return Err(format!(
                    "\"{kind}\" isn't a valid value for '<item type>'\n\t[possible values: note, nt, folder, fd]\n"
                )
                .into())
            }
        },
        None => None,
    };
    crate::utils::list_items(vault, filter)
}

// --------------------------------------------------------- fs operations ---

fn remove(state: &mut State, kind: &str, name: &str) -> JotResult<()> {
    let kind = ItemKind::from(kind).unwrap();
    Vault::check_name(name)?;
    match kind {
        ItemKind::Vault => {
            let vault = state
                .vaults
                .vault(name)
                .ok_or_else(|| JotError::Message(format!("vault {name} doesn't exist")))?;
            let dir = vault.root();
            fs::remove_dir_all(dir)?;
            state.vaults.remove(name);
        }
        ItemKind::Note => {
            let vault = current_vault(state)?;
            let path = vault.note_path(name);
            if !path.exists() {
                return Err(format!("note {name} not found").into());
            }
            fs::remove_file(path)?;
        }
        ItemKind::Folder => {
            let vault = current_vault(state)?;
            let path = vault.item_path(name);
            if !path.exists() {
                return Err(format!("folder {name} not found").into());
            }
            fs::remove_dir_all(path)?;
        }
    }
    println!("{} {} removed", kind.name(), blue(name));
    Ok(())
}

fn rename(state: &mut State, kind: &str, name: &str, new_name: &str) -> JotResult<()> {
    let kind = ItemKind::from(kind).unwrap();
    Vault::check_name(name)?;
    Vault::check_name(new_name)?;
    if name == new_name {
        return Err("new name is same as old name".into());
    }
    match kind {
        ItemKind::Vault => {
            let vault = state
                .vaults
                .vault(name)
                .ok_or_else(|| JotError::Message(format!("vault {name} doesn't exist")))?;
            let dir = vault.root();
            fs::rename(&dir, dir.with_file_name(new_name))?;
            state.vaults.rename(name, new_name);
        }
        ItemKind::Note => {
            let vault = current_vault(state)?;
            let source = vault.note_path(name);
            if !source.exists() {
                return Err(format!("note {name} not found").into());
            }
            let mut target = vault.item_path(new_name);
            target.set_extension("md");
            fs::rename(source, target)?;
        }
        ItemKind::Folder => {
            let vault = current_vault(state)?;
            let source = vault.item_path(name);
            if !source.exists() {
                return Err(format!("folder {name} not found").into());
            }
            let target = vault.item_path(new_name);
            fs::rename(source, target)?;
        }
    }
    println!(
        "{} {} renamed to {}",
        kind.name(),
        blue(name),
        blue(new_name)
    );
    Ok(())
}

fn move_item(state: &mut State, kind: &str, name: &str, location: &str) -> JotResult<()> {
    let kind = ItemKind::from(kind).unwrap();
    Vault::check_name(name)?;
    match kind {
        ItemKind::Vault => {
            let vault = state
                .vaults
                .vault(name)
                .ok_or_else(|| JotError::Message(format!("vault {name} doesn't exist")))?;
            let target = Path::new(location);
            if !target.is_absolute() {
                return Err("specified path isn't absolute".into());
            }
            let location = target
                .canonicalize()
                .map_err(|_| JotError::Message(String::from("couldn't find the path specified")))?;
            let dir = location.join(name);
            crate::utils::copy_path(&vault.root(), &dir)?;
            fs::remove_dir_all(vault.root())?;
            state.vaults.update_location(name, &location.to_string_lossy());
            state.set_vault_location(name, &location.to_string_lossy());
        }
        _ => {
            let vault = current_vault(state)?;
            let destination = resolve_destination(vault, location)?;
            let source = match kind {
                ItemKind::Note => vault.note_path(name),
                _ => vault.item_path(name),
            };
            if source == destination {
                return Err("new location is same as old location".into());
            }
            if destination.exists() {
                return Err(format!(
                    "a {} named {} already exists in this location",
                    kind.name(),
                    name
                )
                .into());
            }
            crate::utils::copy_path(&source, &destination)?;
            crate::utils::remove_path(&source)?;
        }
    }
    println!("{} {} moved", kind.name(), blue(name));
    Ok(())
}

fn resolve_destination(vault: &Vault, location: &str) -> JotResult<PathBuf> {
    let target = vault.folder_path().join(location);
    if !target.exists() {
        return Err("couldn't find the path specified".into());
    }
    let root = vault.root().canonicalize().unwrap_or_default();
    let target = match target.canonicalize() {
        Ok(path) => path,
        Err(_) => return Err("couldn't find the path specified".into()),
    };
    if !target.starts_with(&root) {
        return Err("path crosses the bounds of vault".into());
    }
    Ok(target)
}

fn vmove(state: &mut State, kind: &str, name: &str, vault_name: &str) -> JotResult<()> {
    let kind = ItemKind::from(kind).unwrap();
    Vault::check_name(name)?;
    let vault = current_vault(state)?;
    let target = state
        .vaults
        .vault(vault_name)
        .ok_or_else(|| JotError::Message(format!("vault {name} doesn't exist")))?;
    let target_dir = target.root();
    let source = match kind {
        ItemKind::Note => vault.note_path(name),
        _ => vault.item_path(name),
    };
    if vault.name() == vault_name {
        println!(
            "{} {} already exists in vault {}",
            kind.name(),
            name,
            target.name()
        );
    }
    let destination = match kind {
        ItemKind::Note => {
            let mut path = target_dir.join(name);
            path.set_extension("md");
            path
        }
        _ => target_dir.join(name),
    };
    if source == destination {
        return Err("new location is same as old location".into());
    }
    if destination.exists() {
        return Err(format!(
            "a {} named {} already exists in this location",
            kind.name(),
            name
        )
        .into());
    }
    crate::utils::copy_path(&source, &destination)?;
    crate::utils::remove_path(&source)?;
    println!(
        "{} {} moved to vault {}",
        kind.name(),
        blue(name),
        blue(vault_name)
    );
    Ok(())
}

// -------------------------------------------------------------- config ----

fn config(
    state: &mut State,
    key: &str,
    value: Option<&str>,
) -> JotResult<()> {
    match value {
        None => match state.config.value(key) {
            Some(value) => println!("{key}: {}", blue(&value)),
            None => {}
        },
        Some(value) => {
            state.config.set(key, value);
            println!("set {} to {}", blue(key), blue(value));
        }
    }
    match value {
        None => open_in_editor(state),
        Some(_) => Ok(()),
    }
}

fn open_in_editor(state: &mut State) -> JotResult<()> {
    let editor = which(&state.config.editor)
        .ok_or_else(|| JotError::Message(String::from("editor not found")))?;
    Command::new(editor)
        .arg(crate::state::config::Config::file())
        .status()?;
    Ok(())
}
