    pub fn set_folder(&mut self, folder: &str) -> JotResult<()> {
        match self.vault.as_mut() {
            Some(vault) => {
                vault.folder = folder.to_string();
                vault.save();
                Ok(())
            }
            None => Ok(()),
        }
    }

    /// Update the location of a vault, keeping the metadata in sync.
    pub fn set_vault_location(&mut self, name: &str, location: &str) -> JotResult<()> {
        let changed = {
            let vault = match self.vault.as_mut() {
                Some(vault) if vault.name.as_deref() == Some(name) => Some(vault),
                _ => None,
            };
            match vault {
                Some(vault) => {
                    vault.location = Some(location.to_string());
                    true
                }
                None => false,
            }
        };
        if changed {
            if let Some(vault) = self.vault.as_ref() {
                vault.save();
            }
