content = '''//! A vault: a folder on disk holding Markdown notes and sub folders.
//!
//! The metadata of a vault lives in `<vault>/.jot/data` and records which
//! folder the user is currently inside, so that the state survives between
//! invocations of the program.

use std::fs;
use std::path::{Path, PathBuf};

use crate::traits::{parse_data, to_toml};
use crate::utils::{blue, read, JotError, JotResult};

/// Name of the folder holding a vault's metadata.
pub const NOTE_DIR: &str = ".jot";

/// Contents of a vault's data file.
///
/// The file is written by the program and looks like this:
///
/// ```toml
/// name = 'work'
/// location = '/home/user/notes'
/// folder = ''
/// history = []
/// ```
///
/// `name` and `location` are optional: a data file may also be written by
/// hand with only part of the information.
#[derive(Debug, serde::Deserialize, serde::Serialize)]
pub struct Vault {
    /// Name of the vault, as registered in the vault registry.
    pub name: Option<String>,
    /// Directory holding the vault.
    pub location: Option<String>,
    /// Folder inside the vault the user is currently in.
    pub folder: String,
    /// Folders visited before the current one.
    pub history: Vec<String>,
}

impl Vault {
    /// Name of the vault, as registered.
    pub fn name(&self) -> &String {
        self.name.as_ref().unwrap()
    }

    /// Folder the user is currently inside.
    pub fn folder(&self) -> &String {
        &self.folder
    }

    /// Directory holding the vault.
    ///
    pub fn location(&self) -> &String {
        self.location.as_ref().unwrap()
    }

    /// Read the data file of the vault registered as `name` in `location`.
    ///
    /// A missing data file is replaced by an (almost empty) one, so that the
    /// user sees an empty vault instead of a hard error.
    pub fn from(name: &str, location: &str) -> Vault {
        let p = data_file(name, location);
        match read(&p) {
            Ok(buf) => parse_data(&buf),
            Err(_) => {
                let empty = Vault {
                    name: None,
                    location: None,
                    folder: String::new(),
                    history: Vec::new(),
                };
                empty.save();
                empty
            }
        }
    }

    /// Root directory of the vault.
    pub fn root(&self) -> PathBuf {
        Path::new(self.location()).join(self.name())
    }

    /// Folder the user is currently inside, as a path.
    pub fn folder_path(&self) -> PathBuf {
        self.root().join(self.folder())
    }

    /// Path of a note called `name` inside the current folder.
    pub fn note_path(&self, name: &str) -> PathBuf {
        let mut path = self.folder_path().join(name);
        path.set_extension("md");
        path
    }

    /// Path of an item called `name` inside the current folder.
    pub fn item_path(&self, name: &str) -> PathBuf {
        self.folder_path().join(name)
    }

    /// Header printed before the contents of the current folder.
    pub fn breadcrumb(&self) -> String {
        if self.folder.is_empty() {
            self.name().clone()
        } else {
            format!("{} > {}", self.name(), self.folder)
        }
    }

    /// Write the vault data back to disk.
    pub fn save(&self) {
        let path = data_file(self.name(), self.location());
        let _ = fs::create_dir_all(path.parent().unwrap_or_default());
        let _ = fs::write(path, to_toml(self));
    }

    /// Ensure the metadata folder of the vault exists.
    pub fn ensure_metadata(&self) {
        let _ = fs::create_dir_all(self.root().join(NOTE_DIR));
    }
}

/// Path of the data file of the vault `name` living in `location`.
pub fn data_file(name: &str, location: &str) -> PathBuf {
    Path::new(location).join(name).join(NOTE_DIR).join("data")
}

/// Verify that a name may be used for a note or a folder.
///
/// Names are single items inside the current folder, so they may not contain
/// a path separator.
pub fn check_name(name: &str) -> JotResult<()> {
    if name.contains('/') {
        Err(JotError::Message(String::from("invalid name")))
    } else {
        Ok(())
    }
}

/// Colour a name the way items are shown in listings.
pub fn colored(name: &str) -> String {
    blue(name)
}
