content = '''//! Registry of vaults: which vaults exist, where they live and which one is
//! currently in use.
//!
//! The registry lives in `~/.local/share/jot/vaults` and maps every vault
//! name to the directory holding it.

pub mod vault;

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;

use crate::traits::{to_toml, FileState};
use crate::utils::data_dir;

/// Contents of the vault registry file, stored in `~/.local/share/jot/vaults`
/// as:
///
/// ```toml
/// current = 'work'
///
/// [vaults]
/// work = '/home/user/notes'
/// ```
///
/// `current` names the vault the user is inside and is absent as long as no
/// vault has been entered.
#[derive(Debug, Deserialize, Serialize)]
pub struct Vaults {
    pub current: Option<String>,
    pub vaults: HashMap<String, String>,
}

impl Vaults {
    /// Vault the user is currently inside, if any.
    pub fn current_vault(&self) -> Option<vault::Vault> {
        let vault_location = self.vaults.get(&self.current.as_ref().unwrap().to_string()).unwrap();
        Some(vault::Vault::from(self.current.as_ref().unwrap(), vault_location))
    }

    /// Vault called `name`, if it is registered.
    pub fn vault(&self, name: &str) -> Option<vault::Vault> {
        self.vaults
            .get(name)
            .map(|location| vault::Vault::from(name, location))
    }

    /// Registry used when no file exists yet.
    pub fn initial() -> Vaults {
        Vaults {
            current: None,
            vaults: HashMap::new(),
        }
    }

    /// Register a new vault.
    pub fn add(&mut self, name: &str, location: &str) {
        self.vaults.insert(name.to_string(), location.to_string());
        self.save();
    }

    /// Forget a vault.
    pub fn remove(&mut self, name: &str) {
        self.vaults.remove(name);
        if self.current.as_deref() == Some(name) {
            self.current = None;
        }
        self.save();
    }

    /// Rename a vault in the registry.
    pub fn rename(&mut self, from: &str, to: &str) {
        if let Some(location) = self.vaults.remove(from) {
            self.vaults.insert(to.to_string(), location);
        }
        if self.current.as_deref() == Some(from) {
            self.current = Some(to.to_string());
        }
        self.save();
    }

    /// Change the directory a vault is looked up in.
    pub fn update_location(&mut self, name: &str, location: &str) {
        if let Some(entry) = self.vaults.get_mut(name) {
            *entry = location.to_string();
        }
        self.save();
    }

    /// Remember the vault the user entered.
    pub fn set_current(&mut self, name: &str) {
        self.current = Some(name.to_string());
        self.save();
    }

    /// Forget the vault the user was inside.
    pub fn clear_current(&mut self) {
        self.current = None;
        self.save();
    }
}

impl FileState for Vaults {
    fn file() -> PathBuf {
        data_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join("jot")
            .join("vaults")
    }

    fn initial() -> String {
        to_toml(&Vaults::initial())
    }

    fn to_toml(&self) -> String {
        to_toml(self)
    }
}
