use serde::{Deserialize, Serialize};
use std::path::PathBuf;

use crate::traits::{to_toml, FileState};
use crate::utils::config_dir;

/// Contents of the configuration file.
///
/// ```toml
/// editor = 'nvim'
/// conflict = true
/// ```
///
/// The file is created with these defaults the first time the program runs,
/// and rewritten whenever a setting is changed.
#[derive(Debug, Deserialize, Serialize)]
pub struct Config {
    /// Program used to open notes (and the config itself).
    pub editor: String,
    /// Whether moving or renaming may overwrite an existing item.
    pub conflict: bool,
}

impl Config {
    /// Configuration used when no file exists yet.
    pub fn initial() -> Config {
        Config {
            editor: String::from("nvim"),
            conflict: true,
        }
    }

    /// Editor the user asked for.
    pub fn editor(&self) -> &String {
        &self.editor
    }

    /// Whether overwriting an existing item is allowed.
    ///
    /// The setting only decides what happens when a note or a folder is moved
    /// onto a place where an item of the same name already lives.
    pub fn conflict_allowed(&self) -> bool {
        self.conflict
    }

    /// Value of a config item, ready to be displayed.
    ///
    /// Only the two known items have a value; anything else is reported as
    /// missing by the caller.
    pub fn value(&self, key: &str) -> Option<String> {
        match key {
            "editor" => Some(self.editor.clone()),
            "conflict" => Some(self.conflict.to_string()),
            _ => None,
        }
    }

    /// Update a config item and persist the change.
    ///
    /// The value of `conflict` has to be a boolean: anything else is treated
    /// as a hard error because the configuration would end up unusable.
    pub fn set(&mut self, key: &str, value: &str) {
        if key == "editor" {
            self.editor = value.to_string();
        } else if key == "conflict" {
            let flag = value.parse::<bool>().unwrap();
            self.conflict = flag;
        }
        self.save();
    }
}

