    let values = &parsed.values;
    match parsed.index {
        0 => vault(state, parsed.flag_l, values),
        1 => note(state, &values[0]),
        2 => folder(state, &values[0]),
        3 => enter(state, &values[0]),
        4 => open(state, &values[0]),
        5 => opdir(state),
        6 => chdir(state, &values[0]),
        7 => list(state, values.first().map(|s| s.as_str())),
        8 => remove(state, &values[0], &values[1]),
        9 => rename(state, &values[0], &values[1], &values[2]),
        10 => move_item(state, &values[0], &values[1], &values[2]),
        11 => vmove(state, &values[0], &values[1], &values[2]),
        12 => config(state, &values[0], values.get(1).map(|s| s.as_str())),
        _ => Ok(()),
    }
}

fn current(state: &State) -> JotResult<&Vault> {
    state
        .vault
        .as_ref()
        .ok_or_else(|| JotError::Message(String::from("not inside a vault")))
}

// ---------------------------------------------------------------- vaults ----

fn vault(state: &mut State, locations: bool, values: &[String]) -> JotResult<()> {
    if values.is_empty() {
        for (name, location) in state.vaults.vaults.iter() {
            let marker = if state.vaults.current.as_deref() == Some(name) {
                "\u{1f449} "
            } else {
                "   "
            };
            if locations {
                println!("{marker}{} \t {location}", blue(name));
            } else {
                println!("{marker}{}", blue(name));
            }
        }
        return Ok(());
    }
    create_vault(state, &values[0], &values[1])
}

fn create_vault(state: &mut State, name: &str, location: &str) -> JotResult<()> {
    if state.vaults.vaults.contains_key(name) {
        return Err(format!("vault {name} already exists").into());
    }
    let given = Path::new(location);
    if !given.is_absolute() {
        return Err("specified path isn't absolute".into());
    }
    let location = given.canonicalize()?;
    let dir = location.join(name);
    if dir.exists() {
        return Err(format!("a folder named {name} already exists in this location").into());
    }
    fs::create_dir(&dir)?;
    fs::create_dir_all(dir.join(NOTE_DIR))?;
    let text = location.to_string_lossy().into_owned();
    let vault = Vault {
        name: Some(name.to_string()),
        location: Some(text.clone()),
        folder: String::new(),
        history: Vec::new(),
    };
    vault.save();
    state.vaults.add(name, &text);
    println!("vault {} created", blue(name));
    Ok(())
}

fn enter(state: &mut State, name: &str) -> JotResult<()> {
    if state.vaults.current.as_deref() == Some(name) {
        return Err(format!("already in vault {name}").into());
    }
    if state.vaults.vaults.get(name).is_none() {
        return Err(format!("vault {name} doesn't exist").into());
    }
    state.vaults.set_current(name);
    println!("entered {}", blue(name));
    Ok(())
}

// --------------------------------------------------------------- items -----

fn note(state: &mut State, name: &str) -> JotResult<()> {
    let vault = current(state)?;
    let item = Item::new(vault, name);
    vault::check_name(name)?;
    let path = item.note();
    if !vault.folder_path().exists() {
        return Err("couldn't find the path specified".into());
    }
    if path.exists() {
        return Err(format!("a note named {name} already exists in this location").into());
    }
    fs::File::create(&path)?;
    println!("note {} created", blue(name));
    Ok(())
}

fn folder(state: &mut State, name: &str) -> JotResult<()> {
    let vault = current(state)?;
    let item = Item::new(vault, name);
    vault::check_name(name)?;
    let path = item.path.clone();
    if !vault.folder_path().exists() {
        return Err("couldn't find the path specified".into());
    }
    if path.exists() {
        return Err(format!("a folder named {name} already exists in this location").into());
    }
    fs::create_dir(&path)?;
    println!("folder {} created", blue(name));
    Ok(())
}

fn open(state: &mut State, name: &str) -> JotResult<()> {
    let vault = current(state)?;
    let item = Item::new(vault, name);
    vault::check_name(name)?;
    let path = item.note();
    if !path.exists() {
        return Err(format!("note {name} not found").into());
    }
    let editor = which(state.config.editor())
        .ok_or_else(|| JotError::Message(String::from("editor not found")))?;
    Command::new(editor).arg(path).status()?;
    Ok(())
}

fn opdir(state: &mut State) -> JotResult<()> {
    let vault = current(state)?;
    let path = vault.folder_path();
    Command::new("xdg-open").arg(path).spawn()?;
    Ok(())
}

fn chdir(state: &mut State, path: &str) -> JotResult<()> {
    let vault = current(state)?;
    let target = vault.folder_path().join(path);
    if !target.exists() {
        return Err("couldn't find the path specified".into());
    }
    let root = vault.root().canonicalize()?;
    let target = target.canonicalize()?;
    if !target.starts_with(&root) {
        return Err("path crosses the bounds of vault".into());
    }
    if target == vault.folder_path().canonicalize()? {
        return Err("new location is same as old location".into());
    }
    let relative = target
        .strip_prefix(&root)
        .map(|p| p.to_string_lossy().into_owned())
        .unwrap_or_default();
    state.set_folder(&relative)
}

fn list(state: &mut State, kind: Option<&str>) -> JotResult<()> {
    let vault = current(state)?;
    let filter = match kind {
        Some(kind) => match ItemKind::from(kind) {
            Some(ItemKind::Note) => Some(true),
            Some(ItemKind::Folder) => Some(false),
            _ => return Err(String::new().into()),
        },
        None => None,
    };
    list_items(vault, filter)
}

// --------------------------------------------------------- fs operations ---

fn remove(state: &mut State, kind: &str, name: &str) -> JotResult<()> {
    let kind = ItemKind::from(kind).unwrap();
    match kind {
        ItemKind::Vault => {
            let dir = registered(state, name)?.root();
            fs::remove_dir_all(dir)?;
            state.vaults.remove(name);
            if state.vaults.current.is_none() {
                state.vault = None;
            }
        }
        ItemKind::Note => {
            let vault = current(state)?;
            let item = Item::new(vault, name);
            vault::check_name(name)?;
            let path = item.note();
            if !path.exists() {
                return Err(format!("note {name} not found").into());
            }
            fs::remove_file(path)?;
        }
        ItemKind::Folder => {
            let vault = current(state)?;
            let item = Item::new(vault, name);
            vault::check_name(name)?;
            let path = item.path.clone();
            if !path.exists() {
                return Err(format!("folder {name} not found").into());
            }
            fs::remove_dir_all(path)?;
        }
    }
    println!("{} {} removed", kind.name(), blue(name));
    Ok(())
}

fn registered(state: &State, name: &str) -> JotResult<Vault> {
    state
        .vaults
        .vault(name)
        .ok_or_else(|| JotError::Message(format!("vault {name} doesn't exist")))
}

fn rename(state: &mut State, kind: &str, name: &str, new_name: &str) -> JotResult<()> {
    let kind = ItemKind::from(kind).unwrap();
    vault::check_name(name)?;
    vault::check_name(new_name)?;
    if name == new_name {
        return Err("new name is same as old name".into());
    }
    match kind {
        ItemKind::Vault => {
            let vault = registered(state, name)?;
            let dir = vault.root();
            let target = dir.with_file_name(new_name);
            fs::rename(&dir, &target)?;
            let mut vault = Vault::from(new_name, vault.location());
            vault.name = Some(new_name.to_string());
            vault.save();
            state.vaults.rename(name, new_name);
        }
        ItemKind::Note => {
            let vault = current(state)?;
            let item = Item::new(vault, name);
            let source = item.note();
            if !source.exists() {
                return Err(format!("note {name} not found").into());
            }
            let target = Item::new(vault, new_name).note();
            fs::rename(source, target)?;
        }
        ItemKind::Folder => {
            let vault = current(state)?;
            let item = Item::new(vault, name);
            let source = item.path.clone();
            if !source.exists() {
                return Err(format!("folder {name} not found").into());
            }
            let target = Item::new(vault, new_name).path;
            fs::rename(source, target)?;
        }
    }
    println!(
        "{} {} renamed to {}",
        kind.name(),
        blue(name),
        blue(new_name)
    );
    Ok(())
}

/// Folder the item is moved into, verified to be inside the vault.
fn destination(vault: &Vault, location: &str) -> JotResult<PathBuf> {
    let target = vault.folder_path().join(location);
    if !target.exists() {
        return Err("couldn't find the path specified".into());
    }
    let root = vault.root().canonicalize()?;
    let target = target.canonicalize()?;
    if !target.starts_with(&root) {
        return Err("path crosses the bounds of vault".into());
    }
    Ok(target)
}

fn move_item(state: &mut State, kind: &str, name: &str, location: &str) -> JotResult<()> {
    let kind = ItemKind::from(kind).unwrap();
    match kind {
        ItemKind::Vault => {
            let vault = registered(state, name)?;
            let given = Path::new(location);
            if !given.is_absolute() {
                return Err("specified path isn't absolute".into());
            }
            let location = given.canonicalize()?;
            if location.to_string_lossy() == vault.location().as_str() {
                return Err("new location is same as old location".into());
            }
            let dir = location.join(name);
            if dir.exists() {
                return Err(format!("a folder named {name} already exists in this location").into());
            }
            copy_path(&vault.root(), &dir)?;
            fs::remove_dir_all(vault.root())?;
            let text = location.to_string_lossy().into_owned();
            let mut vault = Vault::from(name, &text);
            vault.location = Some(text.clone());
            vault.save();
            state.vaults.update_location(name, &text);
        }
        _ => {
            let vault = current(state)?;
            let target = destination(vault, location)?;
            let source = match kind {
                ItemKind::Note => Item::new(vault, name).note(),
                _ => Item::new(vault, name).path,
            };
            vault::check_name(name)?;
            if source == target.join(item_file_name(&source)) {
                return Err("new location is same as old location".into());
            }
            let mut destination = target.join(item_file_name(&source));
            if kind == ItemKind::Note {
                destination.set_extension("md");
            }
            if destination.exists() {
                return Err(format!(
                    "a {} named {} already exists in this location",
                    kind.name(),
                    name
                )
                .into());
            }
            copy_path(&source, &destination)?;
            crate::utils::remove_path(&source)?;
        }
    }
    println!("{} {} moved", kind.name(), blue(name));
    Ok(())
}

/// Name the moved item keeps at its destination.
fn item_file_name(source: &Path) -> String {
    source
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_default()
}

fn vmove(state: &mut State, kind: &str, name: &str, vault_name: &str) -> JotResult<()> {
    let kind = ItemKind::from(kind).unwrap();
    let vault = current(state)?;
    let target = state
        .vaults
        .vault(vault_name)
        .ok_or_else(|| JotError::Message(format!("vault {name} doesn't exist")))?;
    vault::check_name(name)?;
    let item = Item::new(vault, name);
    let source = match kind {
        ItemKind::Note => item.note(),
        _ => item.path.clone(),
    };
    if vault.name().as_str() == vault_name {
        println!(
            "{} {} already exists in vault {}",
            kind.name(),
            name,
            target.name()
        );
    }
    let destination = match kind {
        ItemKind::Note => Item::new(&target, name).note(),
        _ => Item::new(&target, name).path,
    };
    if source == destination {
        return Err("new location is same as old location".into());
    }
    if destination.exists() {
        return Err(format!(
            "a {} named {} already exists in this location",
            kind.name(),
            name
        )
        .into());
    }
    copy_path(&source, &destination)?;
    crate::utils::remove_path(&source)?;
    println!(
        "{} {} moved to vault {}",
        kind.name(),
        blue(name),
        blue(vault_name)
    );
    Ok(())
}

// -------------------------------------------------------------- config ----

fn config(state: &mut State, key: &str, value: Option<&str>) -> JotResult<()> {
    match value {
        None => match state.config.value(key) {
            Some(value) => println!("{key}: {}", blue(&value)),
            None => {}
        },
        Some(value) => {
            state.config.set(key, value);
            println!("set {} to {}", blue(key), blue(value));
        }
    }
    Ok(())
}

/// Open the configuration file in the configured editor.
pub fn open_config(state: &mut State) -> JotResult<()> {
    let editor = which(state.config.editor())
        .ok_or_else(|| JotError::Message(String::from("editor not found")))?;
    Command::new(editor)
        .arg(crate::state::config::Config::file())
        .status()?;
    Ok(())
}
