            let vault = registered(state, name)?;
            let dir = vault.root();
            let target = dir.with_file_name(new_name);
            fs::rename(&dir, &target)?;
            let mut vault = Vault::from(new_name, vault.location());
            vault.name = Some(new_name.to_string());
            vault.save();
            state.vaults.rename(name, new_name);
        }
        ItemKind::Note => {
            let vault = current(state)?;
            let item = Item::new(vault, name);
            let source = item.note();
            if !source.exists() {
                return Err(format!("note {name} not found").into());
            }
            let target = Item::new(vault, new_name).note();
            fs::rename(source, target)?;
        }
        ItemKind::Folder => {
            let vault = current(state)?;
            let item = Item::new(vault, name);
            let source = item.path.clone();
            if !source.exists() {
                return Err(format!("folder {name} not found").into());
            }
            let target = Item::new(vault, new_name).path;
            fs::rename(source, target)?;
        }
    }
    println!(
        "{} {} renamed to {}",
        kind.name(),
        blue(name),
        blue(new_name)
    );
    Ok(())
}

/// Folder the item is moved into, verified to be inside the vault.
fn destination(vault: &Vault, location: &str) -> JotResult<PathBuf> {
    let target = vault.folder_path().join(location);
    if !target.exists() {
        return Err("couldn't find the path specified".into());
    }
    let root = vault.root().canonicalize()?;
    let target = target.canonicalize()?;
    if !target.starts_with(&root) {
        return Err("path crosses the bounds of vault".into());
    }
    Ok(target)
}

fn move_item(state: &mut State, kind: &str, name: &str, location: &str) -> JotResult<()> {
    let kind = ItemKind::from(kind).unwrap();
    match kind {
        ItemKind::Vault => {
            let vault = registered(state, name)?;
            let given = Path::new(location);
            if !given.is_absolute() {
                return Err("specified path isn't absolute".into());
            }
            let location = given.canonicalize()?;
            if location.to_string_lossy() == vault.location().as_str() {
                return Err("new location is same as old location".into());
            }
            let dir = location.join(name);
            if dir.exists() {
                return Err(format!("a folder named {name} already exists in this location").into());
            }
            copy_path(&vault.root(), &dir)?;
            fs::remove_dir_all(vault.root())?;
            let text = location.to_string_lossy().into_owned();
            let mut vault = Vault::from(name, &text);
            vault.location = Some(text.clone());
            vault.save();
            state.vaults.update_location(name, &text);
        }
        _ => {
            let vault = current(state)?;
            let target = destination(vault, location)?;
            let source = match kind {
                ItemKind::Note => Item::new(vault, name).note(),
                _ => Item::new(vault, name).path,
            };
            vault::check_name(name)?;
            if source == target.join(item_file_name(&source)) {
                return Err("new location is same as old location".into());
            }
            let mut destination = target.join(item_file_name(&source));
            if kind == ItemKind::Note {
                destination.set_extension("md");
            }
            if destination.exists() {
                return Err(format!(
                    "a {} named {} already exists in this location",
                    kind.name(),
                    name
                )
                .into());
            }
            copy_path(&source, &destination)?;
            crate::utils::remove_path(&source)?;
        }
    }
    println!("{} {} moved", kind.name(), blue(name));
    Ok(())
}

/// Name the moved item keeps at its destination.
fn item_file_name(source: &Path) -> String {
    source
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_default()
}

fn vmove(state: &mut State, kind: &str, name: &str, vault_name: &str) -> JotResult<()> {
    let kind = ItemKind::from(kind).unwrap();
    let vault = current(state)?;
    let target = state
        .vaults
        .vault(vault_name)
        .ok_or_else(|| JotError::Message(format!("vault {name} doesn't exist")))?;
    vault::check_name(name)?;
    let item = Item::new(vault, name);
    let source = match kind {
        ItemKind::Note => item.note(),
        _ => item.path.clone(),
    };
    if vault.name().as_str() == vault_name {
        println!(
            "{} {} already exists in vault {}",
            kind.name(),
            name,
            target.name()
        );
    }
    let destination = match kind {
        ItemKind::Note => Item::new(&target, name).note(),
        _ => Item::new(&target, name).path,
    };
    if source == destination {
        return Err("new location is same as old location".into());
    }
    if destination.exists() {
        return Err(format!(
            "a {} named {} already exists in this location",
            kind.name(),
            name
        )
        .into());
    }
    copy_path(&source, &destination)?;
    crate::utils::remove_path(&source)?;
    println!(
        "{} {} moved to vault {}",
        kind.name(),
        blue(name),
        blue(vault_name)
    );
    Ok(())
}

// -------------------------------------------------------------- config ----

fn config(state: &mut State, key: &str, value: Option<&str>) -> JotResult<()> {
    match value {
        None => match state.config.value(key) {
            Some(value) => println!("{key}: {}", blue(&value)),
            None => {}
        },
        Some(value) => {
            state.config.set(key, value);
            println!("set {} to {}", blue(key), blue(value));
        }
    }
    Ok(())
}

/// Open the configuration file in the configured editor.
pub fn open_config(state: &mut State) -> JotResult<()> {
    let editor = which(state.config.editor())
        .ok_or_else(|| JotError::Message(String::from("editor not found")))?;
    Command::new(editor)
        .arg(crate::state::config::Config::file())
        .status()?;
    Ok(())
}
