/*@PAD@*/

use serde::de::DeserializeOwned;
use serde::Serialize;
use std::fs;
use std::path::PathBuf;

/// Parse a TOML document, aborting when the data cannot be understood.
pub fn parse_data<T: DeserializeOwned>(data: &str) -> T {
    match toml::from_str(data) {
        Ok(value) => value,
        Err(err) => panic!("couldn't parse data"),
    }
}

/// Serialise a value into TOML text.
pub fn to_toml<T: Serialize>(value: &T) -> String {
    toml::to_string(value).unwrap_or_default()
}

/// Directory holding `path`, or the current directory when it has none.
fn parent_of(path: &Path) -> PathBuf {
    path.parent().map(|p| p.to_path_buf()).unwrap_or_default()
}

/// Anything that can be persisted as a TOML document.
pub trait FileState: Sized + DeserializeOwned {
    /// Path of the file backing this state.
    fn file() -> PathBuf;
    /// Contents written when the file is missing.
    fn initial() -> String;

    /// Read the state from disk, creating the file when it is missing.
    fn load() -> Self {
        let path = Self::file();
        match fs::read_to_string(&path) {
            Ok(data) => parse_data(&data),
            Err(_) => {
                let initial = Self::initial();
                let _ = fs::create_dir_all(parent_of(&path));
                let _ = fs::write(&path, &initial);
                parse_data(&initial)
            }
        }
    }

    /// Write the state back to disk.
    fn save(&self) {
        let _ = fs::create_dir_all(parent_of(&Self::file()));
        let _ = fs::write(Self::file(), self.to_toml());
    }

    /// Convert the state into TOML text.
    fn to_toml(&self) -> String;
}
