    Str(String),
    Bool(bool),
    Array(Vec<Value>),
    Table(Vec<(String, Value)>),
    /// Numbers, dates and anything else the program never reads back.
    Other,
}

impl Value {
    /// Value stored under `key`, if any.
    pub fn get(&self, key: &str) -> Option<&Value> {
        match self {
            Value::Table(entries) => entries.iter().rev().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }

    /// Value as a string.
    pub fn as_str(&self) -> Option<&str> {
        match self {
            Value::Str(s) => Some(s),
            _ => None,
        }
    }

    /// Value as a boolean.
    pub fn as_bool(&self) -> Option<bool> {
        match self {
            Value::Bool(b) => Some(*b),
            _ => None,
        }
    }

    /// Value as a (possibly empty) array.
    pub fn as_array(&self) -> Option<&Vec<Value>> {
        match self {
            Value::Array(items) => Some(items),
            _ => None,
        }
    }

    /// Value as a table.
    pub fn as_table(&self) -> Option<&Vec<(String, Value)>> {
        match self {
            Value::Table(entries) => Some(entries),
            _ => None,
        }
    }
}

pub struct Parser<'a> {
    src: Vec<char>,
    pos: usize,
    phantom: std::marker::PhantomData<&'a str>,
}

type Parsed = Result<Value, ()>;

impl<'a> Parser<'a> {
    pub fn new(text: &'a str) -> Parser<'a> {
        Parser {
            src: text.chars().collect(),
            pos: 0,
            phantom: std::marker::PhantomData,
        }
    }

    fn peek(&self) -> Option<char> {
        self.src.get(self.pos).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<char> {
        self.src.get(self.pos + offset).copied()
    }

    fn bump(&mut self) -> Option<char> {
        let ch = self.peek();
        if ch.is_some() {
            self.pos += 1;
        }
        ch
    }

    fn eat(&mut self, expected: char) -> bool {
        if self.peek() == Some(expected) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    /// Skip spaces, newlines and comments.
    fn trivia(&mut self) -> Result<(), ()> {
        loop {
            match self.peek() {
                Some(' ') | Some('\t') | Some('\n') | Some('\r') => {
                    self.pos += 1;
                }
                Some('#') => {
                    while let Some(ch) = self.peek() {
                        if ch == '\n' {
                            break;
                        }
                        self.pos += 1;
                    }
                }
                _ => return Ok(()),
            }
        }
    }

    /// End of the current line: only blanks and a comment may follow.
    fn end_of_line(&mut self) -> Result<(), ()> {
        loop {
            match self.peek() {
                Some(' ') | Some('\t') | Some('\r') => {
                    self.pos += 1;
                }
                Some('#') => {
                    while let Some(ch) = self.peek() {
                        if ch == '\n' {
                            break;
                        }
                        self.pos += 1;
                    }
                }
                Some('\n') | None => return Ok(()),
                _ => return Err(()),
            }
        }
    }

    /// Read a whole document, keeping the entries of every table.
    pub fn document(&mut self) -> Parsed {
        let mut root: Vec<(String, Value)> = Vec::new();
        let mut path: Vec<String> = Vec::new();
        loop {
            self.trivia()?;
            if self.peek().is_none() {
                break;
            }
            if self.peek() == Some('[') {
                self.pos += 1;
                if self.peek() == Some('[') {
                    return Err(());
                }
                let key = self.key_path()?;
                if !self.eat(']') {
                    return Err(());
                }
                self.end_of_line()?;
                self.trivia()?;
                self.declare(&mut root, &key)?;
                path = key;
                continue;
            }
            let key = self.key_path()?;
            self.trivia()?;
            if !self.eat('=') {
                return Err(());
            }
            self.trivia()?;
            let value = self.value()?;
            self.end_of_line()?;
            self.assign(&mut root, &path, &key, value)?;
        }
        Ok(Value::Table(root))
    }

    /// Make sure the table `path` exists and is not defined twice.
    fn declare(&self, root: &mut Vec<(String, Value)>, path: &[String]) -> Result<(), ()> {
        let mut table = root;
        for (index, part) in path.iter().enumerate() {
            let last = index + 1 == path.len();
            let found = table.iter().position(|(k, _)| k == part);
            match found {
                Some(index) => {
                    if last {
                        return Err(());
                    }
                    match &mut table[index].1 {
                        Value::Table(entries) => table = entries,
                        _ => return Err(()),
                    }
                }
                None => {
                    table.push((part.clone(), Value::Table(Vec::new())));
                    let index = table.len() - 1;
                    match &mut table[index].1 {
                        Value::Table(entries) => table = entries,
                        _ => return Err(()),
                    }
                }
            }
        }
        Ok(())
    }

    /// Store `value` under `key` inside the table currently being filled.
    fn assign(
        &self,
        root: &mut Vec<(String, Value)>,
        path: &[String],
        key: &str,
        value: Value,
    ) -> Result<(), ()> {
        let mut table = root;
        for part in path {
            let index = table.iter().position(|(k, _)| k == part).ok_or(())?;
            match &mut table[index].1 {
                Value::Table(entries) => table = entries,
                _ => return Err(()),
            }
        }
        let dotted: Vec<&str> = key.split('.').collect();
        for (index, part) in dotted.iter().enumerate() {
            let last = index + 1 == dotted.len();
            let found = table.iter().position(|(k, _)| k == part);
            match found {
                Some(index) => {
                    if last {
                        table[index].1 = value;
                        return Ok(());
                    }
                    match &mut table[index].1 {
                        Value::Table(entries) => table = entries,
                        _ => return Err(()),
                    }
                }
                None => {
                    if last {
                        table.push(((*part).to_string(), value));
                        return Ok(());
                    }
                    table.push(((*part).to_string(), Value::Table(Vec::new())));
                    let index = table.len() - 1;
                    match &mut table[index].1 {
                        Value::Table(entries) => table = entries,
                        _ => return Err(()),
                    }
                }
            }
        }
        Ok(())
    }

    /// Key, possibly made of several dotted parts.
    fn key_path(&mut self) -> Result<Vec<String>, ()> {
        let mut parts = vec![self.key()?];
        loop {
            self.trivia()?;
            if self.peek() == Some('.') {
                self.pos += 1;
                self.trivia()?;
                parts.push(self.key()?);
            } else {
                break;
            }
        }
        Ok(parts)
    }

    /// Single key, either bare or quoted.
    fn key(&mut self) -> Result<String, ()> {
        match self.peek() {
            Some('\'') => self.literal_string(),
            Some('"') => self.basic_string(),
            _ => {
                let mut out = String::new();
                while let Some(ch) = self.peek() {
                    if ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' {
                        out.push(ch);
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                if out.is_empty() {
                    Err(())
                } else {
                    Ok(out)
                }
            }
        }
    }

    fn value(&mut self) -> Parsed {
        match self.peek() {
            Some('\'') => {
                if self.peek_at(1) == Some('\'') && self.peek_at(2) == Some('\'') {
                    self.multiline_literal()
                } else {
                    self.literal_string().map(Value::Str)
                }
            }
            Some('"') => {
                if self.peek_at(1) == Some('"') && self.peek_at(2) == Some('"') {
                    self.multiline_basic()
                } else {
                    self.basic_string().map(Value::Str)
                }
            }
            Some('[') => self.array(),
            Some('{') => self.inline_table(),
            _ => self.bare_value(),
        }
    }

    fn literal_string(&mut self) -> Result<String, ()> {
        self.pos += 1;
        let mut out = String::new();
        loop {
            match self.bump() {
                Some('\'') => return Ok(out),
                Some('\n') | None => return Err(()),
                Some(ch) => out.push(ch),
            }
        }
    }

    fn basic_string(&mut self) -> Result<String, ()> {
        self.pos += 1;
        let mut out = String::new();
        loop {
            match self.bump() {
                Some('"') => return Ok(out),
                Some('\\') => out.push(self.escape()?),
                Some('\n') | None => return Err(()),
                Some(ch) => out.push(ch),
            }
        }
    }

    fn escape(&mut self) -> Result<char, ()> {
        match self.bump() {
            Some('b') => Ok('\u{8}'),
            Some('t') => Ok('\t'),
            Some('n') => Ok('\n'),
            Some('f') => Ok('\u{c}'),
            Some('r') => Ok('\r'),
            Some('"') => Ok('"'),
            Some('\\') => Ok('\\'),
            Some('u') => self.hex_escape(4),
            Some('U') => self.hex_escape(8),
            _ => Err(()),
        }
    }

    fn hex_escape(&mut self, digits: usize) -> Result<char, ()> {
        let mut value: u32 = 0;
        for _ in 0..digits {
            let ch = self.bump().ok_or(())?;
            let digit = ch.to_digit(16).ok_or(())?;
            value = value * 16 + digit;
        }
        char::from_u32(value).ok_or(())
    }

    fn multiline_literal(&mut self) -> Parsed {
        self.pos += 3;
        if self.peek() == Some('\n') {
            self.pos += 1;
        } else if self.peek() == Some('\r') && self.peek_at(1) == Some('\n') {
            self.pos += 2;
        }
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Err(()),
                Some('\'') if self.peek_at(1) == Some('\'') && self.peek_at(2) == Some('\'') => {
                    self.pos += 3;
                    return Ok(Value::Str(out));
                }
                Some(ch) => {
                    out.push(ch);
                    self.pos += 1;
                }
            }
        }
    }

    fn multiline_basic(&mut self) -> Parsed {
        self.pos += 3;
        if self.peek() == Some('\n') {
            self.pos += 1;
        } else if self.peek() == Some('\r') && self.peek_at(1) == Some('\n') {
            self.pos += 2;
        }
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Err(()),
                Some('"') if self.peek_at(1) == Some('"') && self.peek_at(2) == Some('"') => {
                    self.pos += 3;
                    return Ok(Value::Str(out));
                }
                Some('\\') => {
                    self.pos += 1;
                    match self.peek() {
                        Some('\n') | Some('\r') | Some(' ') | Some('\t') => {
                            while let Some(ch) = self.peek() {
                                if ch == '\n' || ch == '\r' || ch == ' ' || ch == '\t' {
                                    self.pos += 1;
                                } else {
                                    break;
                                }
                            }
                        }
                        _ => out.push(self.escape()?),
                    }
                }
                Some(ch) => {
                    out.push(ch);
                    self.pos += 1;
                }
            }
        }
    }

    fn array(&mut self) -> Parsed {
        self.pos += 1;
        let mut items: Vec<Value> = Vec::new();
        loop {
            self.trivia()?;
            if self.eat(']') {
                return Ok(Value::Array(items));
            }
            let value = self.value()?;
            items.push(value);
            self.trivia()?;
            if self.eat(',') {
                continue;
            }
            self.trivia()?;
            if self.eat(']') {
                return Ok(Value::Array(items));
            }
            return Err(());
        }
    }

    fn inline_table(&mut self) -> Parsed {
        self.pos += 1;
        let mut entries: Vec<(String, Value)> = Vec::new();
        loop {
            self.trivia()?;
            if self.eat('}') {
                return Ok(Value::Table(entries));
            }
            let parts = self.key_path()?;
            self.trivia()?;
            if !self.eat('=') {
                return Err(());
            }
            self.trivia()?;
            let value = self.value()?;
            let key = parts.join(".");
            entries.push((key, value));
            self.trivia()?;
            if self.eat(',') {
                continue;
            }
            self.trivia()?;
            if self.eat('}') {
                return Ok(Value::Table(entries));
            }
            return Err(());
        }
    }

    /// Bare values: booleans, numbers and dates.
    fn bare_value(&mut self) -> Parsed {
        let start = self.pos;
        while let Some(ch) = self.peek() {
            if ch == '\n' || ch == '\r' || ch == ',' || ch == ']' || ch == '}' || ch == '#' {
                break;
            }
            if ch == ' ' || ch == '\t' {
                break;
            }
            self.pos += 1;
        }
        let text: String = self.src[start..self.pos].iter().collect();
        match text.as_str() {
            "true" => Ok(Value::Bool(true)),
            "false" => Ok(Value::Bool(false)),
            "" => Err(()),
            _ => Ok(Value::Other),
        }
    }
}

/// Read a whole TOML document.
pub fn parse(text: &str) -> Result<Value, ()> {
    Parser::new(text).document()
}

/// Directory holding `path`, or the current directory when it has none.
pub fn encode_string(value: &str) -> String {
    let metrics = Metrics::of(value);
    if !metrics.escape_codes && metrics.quotes == 0 && !metrics.newline {
        return format!("'{}'", value);
    }
    if !metrics.escape_codes && metrics.quotes <= 2 {
        if metrics.newline {
            return format!("'''\n{value}'''");
        }
        return format!("'''{value}'''");
    }
    if metrics.newline && !metrics.escape_codes {
        return format!("\"\"\"\n{}\"\"\"", escape_basic(value, true));
    }
    format!("\"{}\"", escape_basic(value, false))
}

/// Encode a key, quoted when it is not a bare key.
pub fn encode_key(key: &str) -> String {
    let bare = !key.is_empty()
        && key
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || ch == '-' || ch == '_');
    if bare {
        key.to_string()
    } else {
        format!("\"{}\"", escape_basic(key, false))
    }
}

fn escape_basic(value: &str, keep_newlines: bool) -> String {
    let mut out = String::new();
    for ch in value.chars() {
        match ch {
            '\u{8}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => {
                if keep_newlines {
                    out.push('\n')
                } else {
                    out.push_str("\\n")
                }
            }
            '\u{c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            ch if (ch as u32) < 0x20 || ch as u32 == 0x7f => {
                out.push_str(&format!("\\u{:04X}", ch as u32))
            }
            ch => out.push(ch),
        }
    }
    out
}

struct Metrics {
    quotes: usize,
    escape_codes: bool,
    newline: bool,
}

impl Metrics {
    fn of(value: &str) -> Metrics {
        let mut metrics = Metrics {
            quotes: 0,
            escape_codes: false,
            newline: false,
        };
        let mut run = 0usize;
        for ch in value.chars() {
            if ch == '\'' {
                run += 1;
                metrics.quotes = metrics.quotes.max(run);
            } else {
                run = 0;
            }
            if ch == '\n' {
                metrics.newline = true;
            }
            let code = ch as u32;
            if code <= 0x1f && code != 0x09 || code == 0x7f {
                metrics.escape_codes = true;
            }
        }
        metrics
    }
}
