/// Jaro similarity of two strings, as used for the "did you mean" hints.
fn jaro(a: &str, b: &str) -> f64 {
    let left: Vec<char> = a.chars().collect();
    let right: Vec<char> = b.chars().collect();
    let a_len = left.len();
    let b_len = right.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    }
    if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    if a_len == 1 && b_len == 1 {
        return if left[0] == right[0] { 1.0 } else { 0.0 };
    }
    let search_range = (a_len.max(b_len) / 2) - 1;
    let mut consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut last_match = 0usize;
    for (i, a_char) in left.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (b_len - 1).min(i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, b_char) in right.iter().enumerate() {
            if min_bound <= j && j <= max_bound && a_char == b_char && !consumed[j] {
                consumed[j] = true;
                matches += 1.0;
                if j < last_match {
                    transpositions += 1.0;
            }
                last_match = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (matches / a_len as f64
            + matches / b_len as f64
            + (matches - transpositions) / matches)
            / 3.0
    }
}

/// Jaro-Winkler similarity, used to rank the suggestions.
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let distance = jaro(a, b);
    let prefix = a
        .chars()
        .zip(b.chars())
        .take_while(|(x, y)| x == y)
        .count();
    let score = distance + 0.1 * prefix as f64 * (1.0 - distance);
    if score <= 1.0 {
        score
    } else {
        1.0
    }
}

/// Commands close enough to `value` to be a likely typo of it.
fn suggestions(value: &str) -> Vec<&'static str> {
    let mut candidates: Vec<(f64, &'static str)> = COMMANDS
        .iter()
        .flat_map(|command| std::iter::once(command.name).chain(command.aliases.iter().copied()))
        .map(|name| (jaro_winkler(value, name), name))
        .filter(|(score, _)| *score > 0.8)
        .collect();
    candidates.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    candidates.into_iter().map(|(_, name)| name).collect()
}
