fn jaro(a: &str, b: &str) -> f64 {
    let left: Vec<char> = a.chars().collect();
    let right: Vec<char> = b.chars().collect();
    let a_len = left.len();
    let b_len = right.len();
    if a_len == 0 && b_len == 0 {
