        let _ = fs::write(path, self.to_toml());
    }
}

/// Path of the data file of the vault `name` living in `location`.
pub fn data_file(name: &str, location: &str) -> PathBuf {
    Path::new(location).join(name).join(NOTE_DIR).join("data")
}

/// Verify that a name may be used for a note or a folder.
///
/// Names are single items inside the current folder, so they may not contain
/// a path separator.
pub fn check_name(name: &str) -> JotResult<()> {
    if name.contains('/') {
        Err(JotError::Message(String::from("invalid name")))
    } else {
        Ok(())
    }
}

impl FromToml for Vault {
    fn from_document(value: &Value) -> Option<Vault> {
        let name = match value.get("name") {
            Some(value) => Some(value.as_str()?.to_string()),
            None => None,
        };
        let location = match value.get("location") {
            Some(value) => Some(value.as_str()?.to_string()),
            None => None,
        };
        let folder = String::from(value.get("folder")?.as_str()?);
        let history = match value.get("history")?.as_array()? {
            items if items.is_empty() => Vec::new(),
            _ => return None,
        };
        Some(Vault {
            name,
            location,
            folder,
            history,
        })
    }
}

impl FileState for Vault {
    /// Path of the data file, when the vault knows where it lives.
    fn file(&self) -> Option<PathBuf> {
        match (&self.name, &self.location) {
            (Some(name), Some(location)) => Some(data_file(name, location)),
            _ => None,
        }
    }

    /// Contents written when the data file is missing.
    fn initial() -> String {
        Vault {
            name: None,
            location: None,
            folder: String::new(),
            history: Vec::new(),
        }
        .to_toml()
    }

    /// Read the vault data, creating the file when it is missing.
    fn load() -> Vault {
        Vault {
            name: None,
            location: None,
            folder: String::new(),
            history: Vec::new(),
        }
    }

    /// Convert the vault data into TOML text.
    fn to_toml(&self) -> String {
        let mut out = String::new();
        if let Some(name) = &self.name {
            out.push_str(&format!("name = {}\\n", encode_string(name)));
        }
        if let Some(location) = &self.location {
            out.push_str(&format!("location = {}\\n", encode_string(location)));
        }
        out.push_str(&format!("folder = {}\\n", encode_string(&self.folder)));
        let items: Vec<String> = self.history.iter().map(|h| encode_string(h)).collect();
        out.push_str(&format!("history = [{}]\\n", items.join(", ")));
        out
    }
}
