use std::io::Result as IoResult;
use std::path::{Path, PathBuf};

use crate::state::vaults::vault::{Vault, NOTE_DIR};

pub const BLUE: &str = "\\x1b[0;34m";
pub const RED: &str = "\\x1b[0;31m";
pub const RESET: &str = "\\x1b[0m";

const TEE: &str = "\\u{251c}\\u{2500}\\u{2500} ";
const ELBOW: &str = "\\u{2514}\\u{2500}\\u{2500} ";
const BAR: &str = "\\u{2502}   ";
const GAP: &str = "    ";

/// Wrap `s` in the blue colour used to highlight values.
pub fn blue(s: &str) -> String {
    format!("{BLUE}{s}{RESET}")
}

/// Print `message` as a red `error: ...` line.
pub fn print_error(message: &str) {
    println!("{}error{}: {message}", RED, RESET);
}

/// The home directory, mirroring the XDG base directory lookup.
pub fn home_dir() -> Option<PathBuf> {
    if let Some(home) = env::var_os("HOME") {
        if !home.is_empty() {
            return Some(PathBuf::from(home));
        }
    }
    passwd_home()
}

fn passwd_home() -> Option<PathBuf> {
    let status = fs::read_to_string("/proc/self/status").ok()?;
    let uid_line = status.lines().find(|line| line.starts_with("Uid:"))?;
    let uid = uid_line.split_whitespace().nth(1)?;
    let passwd = fs::read_to_string("/etc/passwd").ok()?;
    for line in passwd.lines() {
        let fields: Vec<&str> = line.split(':').collect();
        if fields.len() >= 6 && fields[2] == uid {
            return Some(PathBuf::from(fields[5]));
        }
    }
    None
}

/// The XDG config directory (`$XDG_CONFIG_HOME`/jot).
pub fn config_dir() -> Option<PathBuf> {
    if let Some(value) = env::var_os("XDG_CONFIG_HOME") {
        let path = PathBuf::from(&value);
        if !value.is_empty() && path.is_absolute() {
            return Some(path);
        }
    }
    home_dir().map(|home| home.join(".config"))
}

/// The XDG data directory (`$XDG_DATA_HOME`/jot).
pub fn data_dir() -> Option<PathBuf> {
    if let Some(value) = env::var_os("XDG_DATA_HOME") {
        let path = PathBuf::from(&value);
        if !value.is_empty() && path.is_absolute() {
            return Some(path);
        }
    }
    home_dir().map(|home| home.join(".local").join("share"))
}

/// Read a file as UTF-8 text.
pub fn read<P: AsRef<Path>>(path: P) -> IoResult<String> {
    fs::read_to_string(path)
}

/// Locate a program, either as a path or by searching `$PATH`.
pub fn which(program: &str) -> Option<PathBuf> {
    let candidate = Path::new(program);
    if program.contains('/') {
        return if candidate.exists() {
            Some(candidate.to_path_buf())
        } else {
            None
        };
    }
    let path = env::var_os("PATH")?;
    for dir in path.to_string_lossy().split(':') {
        let candidate = Path::new(dir).join(program);
        if candidate.exists() {
            return Some(candidate);
        }
    }
    None
}

/// Error wrapper used throughout the program.
pub enum JotError {
    Message(String),
    Io(IoError),
    Copy(IoError),
}

impl JotError {
    pub fn message(&self) -> String {
        match self {
            JotError::Message(message) => message.clone(),
            JotError::Io(error) => format!("undefined error: {error}"),
            JotError::Copy(error) => error.to_string().to_lowercase(),
        }
    }
}

impl From<IoError> for JotError {
    fn from(error: IoError) -> Self {
        JotError::Io(error)
    }
}

impl From<String> for JotError {
    fn from(message: String) -> Self {
        JotError::Message(message)
    }
}

impl From<&str> for JotError {
    fn from(message: &str) -> Self {
        JotError::Message(message.to_string())
    }
}

pub type JotResult<T> = Result<T, JotError>;

/// Whether an entry should be hidden from a listing.
///
/// Only the metadata folder of a vault is hidden; every other entry (even
/// hidden files) is shown.
fn visible(path: &Path) -> bool {
    path.file_name().map(|name| name != NOTE_DIR).unwrap_or(true)
}

/*@NOTEDOC@*/
fn is_note(path: &Path) -> bool {
    let has_md_ext = path.is_file() && path.extension().unwrap() == "md";
    has_md_ext
}

/// Filter keeping only notes.
fn keep_note(path: &Path) -> bool {
    is_note(path)
}

/// Filter keeping only folders.
fn keep_folder(path: &Path) -> bool {
    path.is_dir()
}

/// Name shown for an entry in a listing.
pub fn item_name(path: &Path) -> String {
    path.file_stem()
        .map(|stem| stem.to_string_lossy().into_owned())
        .unwrap_or_default()
}

/// Entries of a folder matching a filter, in directory order.
///
/// The metadata folder of a vault takes part in the listing of folders and
/// decides which connector is drawn for the neighbours, but it is not shown
/// in an unfiltered listing.
fn filtered(path: &Path, is_note: bool) -> Vec<DirEntry> {
    let dir = fs::read_dir(path).unwrap();
    let mut items: Vec<DirEntry> = Vec::new();
    for entry in dir.flatten() {
        let entry_path = entry.path();
        let keep = if is_note { is_note(&entry_path) } else { entry_path.is_dir() };
        if keep {
            items.push(entry);
        }
    }
    items
}

/// Entries of a folder that take part in an unfiltered listing.
fn entries_of(path: &Path) -> Vec<DirEntry> {
    let dir = fs::read_dir(path).unwrap();
    let mut items: Vec<DirEntry> = Vec::new();
    for entry in dir.flatten() {
        items.push(entry);
    }
    items
}

/// Print the contents of the current folder as a tree.
pub fn list_items(vault: &Vault, filter: Option<bool>) -> JotResult<()> {
    println!("{}", vault.breadcrumb());
    let folder = vault.folder_path();
    match filter {
        Some(only) => {
            let items = filtered(&folder, only);
            draw(&items, "", Some(only));
        }
        None => {
            let items = entries_of(&folder);
            draw(&items, "", None);
        }
    }
    Ok(())
}

fn draw(items: &[DirEntry], prefix: &str, filter: Option<bool>) {
    for (index, entry) in items.iter().enumerate() {
        let last = index + 1 == items.len();
        let path = entry.path();
        let connector = if last { ELBOW } else { TEE };
        let name = item_name(&path);
        if filter.is_none() && !visible(&path) {
            continue;
        }
        if path.is_dir() {
            println!("{prefix}{connector}{name}");
            if filter.is_none() {
                let children = entries_of(&path);
                let inner = format!("{prefix}{}", if last { GAP } else { BAR });
                draw(&children, &inner, filter);
            }
        } else {
            println!("{prefix}{connector}{}", blue(&name));
        }
    }
}

/// Copy a file or a whole folder to `destination`.
pub fn copy_path(source: &Path, destination: &Path) -> JotResult<()> {
    if source.is_dir() {
        let entries: Vec<std::fs::DirEntry> = fs::read_dir(source)
            .map_err(JotError::Copy)?
            .flatten()
            .collect();
        fs::create_dir(destination).map_err(JotError::Copy)?;
        for entry in entries {
            let target = destination.join(entry.file_name());
            copy_path(&entry.path(), &target)?;
        }
        Ok(())
    } else {
        fs::copy(source, destination).map_err(JotError::Copy)?;
        Ok(())
    }
}

/// Remove a file or a whole folder.
pub fn remove_path(path: &Path) -> JotResult<()> {
    if path.is_dir() {
        fs::remove_dir_all(path)?;
    } else {
        fs::remove_file(path)?;
    }
    Ok(())
}
