mid = '''/// Items of a folder matching a filter, in directory order.
///
/// Notes are recognised only when their extension is present, so a file
/// without one aborts the listing.
/// The metadata folder of a vault is hidden from an unfiltered listing but
/// still decides which connector is drawn for its neighbours.
fn filtered(path: &Path, is_note: bool) -> Vec<DirEntry> {
    let dir = fs::read_dir(path).unwrap();
    let mut items: Vec<DirEntry> = Vec::new();
    for entry in dir.flatten() {
        let entry_path = entry.path();
        if if is_note { is_note(&entry_path) } else { entry_path.is_dir() } {
            items.push(entry);
        }
    }
    items
}
fn is_note(path: &Path) -> bool {
    let has_md_ext = path.is_file() && path.extension().unwrap() == "md";
    has_md_ext
}

fn keep_note(path: &Path) -> bool {
    is_note(path)
}

fn keep_folder(path: &Path) -> bool {
    path.is_dir()
}

/// Name shown for an entry in a listing.
///
/// Folders keep their full name, while the extension of a note is dropped
/// so that listings stay short.  Entries without an extension (plain text
/// files, for instance) keep their whole name as well, which is why the
/// extension has to be looked at before a name is shortened.
pub fn item_name(path: &Path) -> String {
    path.file_stem()
        .map(|stem| stem.to_string_lossy().into_owned())
        .unwrap_or_default()
}

/// Entries of a folder that take part in an unfiltered listing.
///
/// The metadata folder of a vault is part of the list (it decides which
/// connector is drawn for the neighbours) but it is not shown itself.
fn entries_of(path: &Path) -> Vec<DirEntry> {
    let dir = fs::read_dir(path).unwrap();
    let mut items: Vec<DirEntry> = Vec::new();
    for entry in dir.flatten() {
        items.push(entry);
    }
    items
}

/// Print the contents of the current folder as a tree.
pub fn list_items(vault: &Vault, filter: Option<bool>) -> JotResult<()> {
    println!("{}", vault.breadcrumb());
    let folder = vault.folder_path();
    match filter {
        Some(only) => {
            let items = filtered(&folder, only);
            draw(&items, "", Some(only));
        }
        None => {
            let items = entries_of(&folder);
            draw(&items, "", None);
        }
    }
    Ok(())
}

fn draw(items: &[DirEntry], prefix: &str, filter: Option<bool>) {
    for (index, entry) in items.iter().enumerate() {
        let last = index + 1 == items.len();
        let path = entry.path();
        let connector = if last { ELBOW } else { TEE };
        let name = item_name(&path);
        if filter.is_none() && path.file_name().map(|n| n == NOTE_DIR).unwrap_or(false) {
            continue;
        }
        if path.is_dir() {
            println!("{prefix}{connector}{name}");
            if filter.is_none() {
                let children = entries_of(&path);
                let inner = format!("{prefix}{}", if last { GAP } else { BAR });
                draw(&children, &inner, filter);
            }
        } else {
            println!("{prefix}{connector}{}", blue(&name));
        }
    }
}

/// Copy a file or a whole folder to `destination`.
pub fn copy_path(source: &Path, destination: &Path) -> JotResult<()> {
    if source.is_dir() {
        let entries: Vec<std::fs::DirEntry> = fs::read_dir(source)
            .map_err(JotError::Copy)?
            .flatten()
            .collect();
        fs::create_dir(destination).map_err(JotError::Copy)?;
        for entry in entries {
            let target = destination.join(entry.file_name());
            copy_path(&entry.path(), &target)?;
        }
        Ok(())
    } else {
        fs::copy(source, destination).map_err(JotError::Copy)?;
        Ok(())
    }
}

/// Remove a file or a whole folder.
pub fn remove_path(path: &Path) -> JotResult<()> {
    if path.is_dir() {
        fs::remove_dir_all(path)?;
    } else {
        fs::remove_file(path)?;
    }
    Ok(())
}
